 $('#inspector').innerHTML=section('当前镜头',sel('拍摄模式','mode',{FREE:'自由模式',TRACK:'跟踪模式'},cfg.mode)+(cfg.mode==='TRACK'?sel('跟踪物品','focusTarget',Object.fromEntries(project.objects.filter(o=>['ACTOR','PROP'].includes(o.role)&&edges(o).length&&!pathErrors(o).length).map(o=>[o.id,o.name])),cfg.focusTarget):'')+`<p class="shot-info">${esc(owner.name)} · ${segment.kind==='DWELL'?'停留点':'运动线段'}<br>${segment.a.position.map(v=>v.toFixed(2)).join(', ')} → ${segment.b.position.map(v=>v.toFixed(2)).join(', ')}<br>${segment.startTime.toFixed(3)}–${segment.endTime.toFixed(3)} 秒 · 时长 ${(segment.endTime-segment.startTime).toFixed(3)} 秒</p>`)+section('视线焦点',(cfg.mode==='FREE'?'<p class="hint">辅助点用于环绕与推进方向；点击“将起始朝向对准焦点”可一次性对准，自由旋转不会被拉回。</p>':`<div id="focusPicker" class="focus-picker"></div><p class="hint">左键点模型表面设置焦点；右键旋转，滚轮缩放。</p>`)+(cfg.mode==='FREE'?cfg.focusWorld:cfg.focusLocal).map((v,i)=>f((cfg.mode==='FREE'?'辅助视点 ':'局部焦点 ')+'XYZ'[i],'focus-'+i,v)).join(''))+section('起始机位',shotStartPanel(cfg,start,index,locked,f,sel))+shotMotionPanel(cfg,start,segment,locked,f,sel)+(cfg.mode==='FREE'?section('路径与关键帧','<button data-action="editCameraPath">编辑相机路径</button>')+keyEditor(editObject(project,c),'angles','关键角度')+keyEditor(editObject(project,c),'lenses','焦距关键帧'):'')+section('预演',`<p class="shot-warning">${esc(error)}</p><div class="inline-actions"><button id="previewShot">当前镜头预演</button><button data-action="export">导出全部视频</button></div><button id="clearShot">取消本段镜头配置</button>`);
