actions.repairGap=()=>change(()=>{const o=active();for(let i=1;i<o.nodes.length;i++){const a=o.nodes[i-1],b=o.nodes[i];if(!o.segments.some(s=>s.start===a.id&&s.end===b.id))o.segments.push({id:id(),start:a.id,end:b.id});}syncSegments(o);retime(o);});

function shotMotionPanel(cfg,start,segment,locked,f,sel){
 const duration=segment.endTime-segment.startTime,free=cfg.orientation==='FREE',delta=cfg.rotationDelta||[0,0,0];
 let movement=sel('运动方式','motion',{TRANSLATE:'单轴平移',DIAGONAL:'斜向平移',DOLLY:'沿视线推进 / 拉远',ORBIT:'环绕'},cfg.motion);
 if(cfg.motion==='ORBIT'&&cfg.controlVersion===3){const focus=shotFocus(cfg,segment.startTime),p=orbitParameters(start.position,focus,cfg.azimuth);movement+=f('方位角 °','azimuth',Number(p.azimuth.toFixed(4)))+f('仰角 °','elevation',Number(p.elevation.toFixed(4)),'min="-89.9" max="89.9"')+f('水平半径（单位）','radius',Number(p.radius.toFixed(4)),'min="0"')+sel('环绕方向','direction',{'1':'逆时针（俯视）','-1':'顺时针（俯视）'},cfg.direction)+f('环绕角度变化量 °','orbitAngle',cfg.orbitAngle,'min="0" max="1000000"')+`<p class="hint">保持水平半径和相对高度，沿 Z 轴环绕；目标移动时圆心随焦点移动。</p><p class="hint" id="orbitGeometryHint">${orbitHint(p)}</p>`;}
 else if(cfg.motion==='ORBIT')movement+=f('轨道倾角 °','tilt',cfg.tilt,'min="0" max="180"')+sel('环绕方向','direction',{'1':'逆时针（沿轨道法线看）','-1':'顺时针（沿轨道法线看）'},cfg.direction)+f('半径（单位）','radius',cfg.orbitFree&&locked?Math.hypot(...start.position.map((x,i)=>x-shotFocus(cfg,segment.startTime)[i])).toFixed(3):cfg.radius,locked&&cfg.orbitFree?'disabled':'min="0.001"')+`<p class="hint">固定一周 360° · ${(360/duration).toFixed(3)}°/s<br>${cfg.orbitFree?'环绕半径由焦点到起点的距离决定；倾角围绕起点方向调整轨道。':'轨道参考轴为世界 X；倾角不是相机 Roll。'}</p><button id="placeOrbitStart" ${locked?'disabled':''}>将独立起点放到此圆轨道上</button>`;
 else if(cfg.motion==='DIAGONAL')movement+=(cfg.velocity||[0,0,0]).map((v,i)=>f('XYZ'[i]+' 速度 单位/秒','velocity-'+i,v)).join('')+`<p class="hint">正数沿正轴，负数沿负轴，0 为不移动。合成速度 ${Math.hypot(...(cfg.velocity||[0,0,0])).toFixed(3)} 单位/秒；附加位移 ${(Math.hypot(...(cfg.velocity||[0,0,0]))*duration).toFixed(3)} 单位。</p>`;
 else movement+=(cfg.motion==='DOLLY'?sel('视线运动方向','direction',{'1':'向焦点推进','-1':'远离焦点拉远'},cfg.direction):sel('世界坐标轴','axis',{X:'X',Y:'Y',Z:'Z'},cfg.axis)+sel('平移方向','direction',{'1':'正方向','-1':'负方向'},cfg.direction))+f('平移速度 单位/秒','speed',cfg.speed,'min="0"')+`<p class="hint">附加位移 ${(cfg.speed*duration).toFixed(3)} 单位。${cfg.motion==='DOLLY'?'方向固定为镜头开始时的三维视线。':cfg.mode==='FREE'?'按世界轴独立移动。':'全程跟随目标。'}</p>`;
 let orientation=cfg.mode==='FREE'?'<p class="hint">自由朝向；辅助视点只用于主动对准。</p>':sel('朝向模式','orientation',{LOCK:'锁定目标',FREE:'自由朝向'},cfg.orientation||'LOCK');
 orientation+=`<p class="hint">${free?'保持起始朝向并叠加旋转。Pan 正值向左、负值向右；Tilt 正值向上、负值向下；Roll 正值让画面顺时针旋转。':'始终朝向焦点；Pan、Tilt 不生效，保留已填数值。Roll 可叠加。'}<br>总角度均匀覆盖本段 ${duration.toFixed(3)} 秒，与位置运动同时开始、同时结束。</p>`;
 orientation+=delta.map((v,i)=>!free&&i<2?'':f(['Pan 总角度 °','Tilt 总角度 °','Roll 总角度 °'][i],'rotationDelta-'+i,Number(deg(v).toFixed(4)))+`<p class="hint">角速度 ${(deg(v)/duration).toFixed(3)}°/s</p>`).join('');
 if(free){const q=locked?cameraQuaternion(start):cfg.start.quaternion;if(q)orientation+=`<details><summary>起始朝向（世界欧拉角）</summary>`+rotationOf(new THREE.Quaternion(...q)).map((v,i)=>f('XYZ'[i]+' °','attitude-'+i,Number(deg(v).toFixed(3)),locked?'disabled':'')).join('')+`<button id="aimShotStart" ${locked?'disabled':''}>将起始朝向对准焦点</button></details>`;}
 else orientation+=f('起始画面 Roll °','roll',Number(deg(locked?start.roll||0:cfg.roll||0).toFixed(4)),locked?'disabled':'');
 return section('位置运动',movement)+section('朝向控制',orientation)+section('镜头焦距',f('起始焦距 mm','lens',cfg.lens,'min="1" max="1000"')+f('结束焦距 mm','lensEnd',cfg.lensEnd??cfg.lens,'min="1" max="1000"'));
}

function finishPathDeletion(o){
 playing=false;previewRange=null;view.previewSegment=null;view.previewOwner=null;view.segmentId=null;view.startEdit=null;shotSelection=null;
 selected=o.id;multi=new Set([o.id]);tab='path';nodeIndex=o.nodes.length?Math.min(Math.max(0,nodeIndex),o.nodes.length-1):-1;
}

function shotStartPanel(cfg,start,index,locked,f,sel){
 const legacy=cfg.controlVersion!==3;if(cfg.mode)return `<p class="hint">独立初始状态；继承仅在设置新镜头时复制一次。</p>`+start.position.map((v,i)=>f('起始机位 '+'XYZ'[i],'start-'+i,Number(v.toFixed(4)))).join('')+'<button id="dragShotStart">在场景中拖动起始机位</button>';
 return (legacy?`<p class="hint">旧版镜头：保留原继承与轨道规则。</p><button id="convertShot">转换为 1.3 独立镜头</button>`+sel('继承上一镜','inherit',{true:'是 · 动态锁定上一镜终点',false:'否 · 独立起点'},cfg.inherit):`<p class="hint">独立镜头。复制上一镜后，两段也不会互相影响。</p><button id="inheritShot" ${index===0?'disabled':''}>复制上一镜结束状态与配置</button>`)+start.position.map((v,i)=>f('起始机位 '+'XYZ'[i],'start-'+i,Number(v.toFixed(4)),locked?'disabled':'')).join('')+`<button id="dragShotStart" ${locked?'disabled':''}>在场景中拖动起始机位</button>`;
}
function orbitHint(p){return p.coincident?'机位与焦点重合：保留起始朝向，可继续拖动。':p.polar?`位于焦点正${p.dz>0?'上':'下'}方，实际仰角 ${p.actualElevation.toFixed(1)}°；输入框显示边界值，修改角度将使用 0.001 单位安全半径。`:`高度差 ${p.dz.toFixed(4)} 单位；修改半径保持高度差，修改仰角保持水平半径。`;}
function syncShotFields(){
 const {cfg,segment}=shotData();if(!cfg||!segment)return;
 disposeFocus?.setLocal?.(cfg.focusLocal);const values={};cfg.start.position.forEach((v,i)=>values['start-'+i]=v);
 if(cfg.controlVersion===3){const p=syncOrbit(project,cfg,segment.startTime);Object.assign(values,{azimuth:p.azimuth,elevation:p.elevation,radius:p.radius});const hint=$('#orbitGeometryHint');if(hint)hint.textContent=orbitHint(p);}
 else if(cfg.motion==='ORBIT'&&cfg.orbitFree)values.radius=cfg.radius;
 for(const [key,value]of Object.entries(values)){const input=$(`[data-shot="${key}"]`);if(input&&input!==document.activeElement)input.value=Number(value.toFixed(4));}
 if(view.startEdit&&!view.dragging){view.startEdit.position=[...cfg.start.position];view.handle.position.fromArray(cfg.start.position);}
}

function shotFocus(cfg,t){return cfg.mode==='FREE'?cfg.focusWorld:new Evaluator(project).focus(project.objects.find(o=>o.id===cfg.focusTarget),cfg.focusLocal,t);}

