function layoutInspector(){
 const el=$('#inspector'),expanded=document.body.classList.contains('inspector-expanded');
 const sections=[...el.querySelectorAll('.section')];sections.forEach((s,i)=>{s.dataset.layoutOrder??=i;});sections.sort((a,b)=>Number(a.dataset.layoutOrder)-Number(b.dataset.layoutOrder));
 for(const section of sections){section.classList.remove('focus-section');el.append(section);}el.querySelectorAll('.settings-column').forEach(c=>c.remove());
 const focus=sections.find(s=>s.querySelector('h3')?.textContent==='视线焦点');document.querySelector('.inspector-panel').classList.toggle('has-shot-layout',expanded&&!!focus);
 if(!expanded||!focus)return;
 focus.classList.add('focus-section');
 const columns=[0,1].map(i=>{const c=document.createElement('div');c.className='settings-column settings-column-'+i;el.append(c);return c;});
 for(const section of sections){if(section===focus)continue;const title=section.querySelector('h3')?.textContent;columns[['当前镜头','起始机位','位置运动','路径与关键帧'].includes(title)?0:1].append(section);}
 el.querySelectorAll('details').forEach(d=>d.open=true);
}
