const sceneResize=$('#sceneResize');
function setSceneWidth(width){const max=Math.max(180,Math.min(600,window.innerWidth-(document.body.classList.contains('inspector-expanded')?window.innerWidth*.5:314)-180));const value=Math.max(160,Math.min(max,width));document.documentElement.style.setProperty('--scene-width',value+'px');sceneResize.setAttribute('aria-valuemin','160');sceneResize.setAttribute('aria-valuemax',String(Math.round(max)));sceneResize.setAttribute('aria-valuenow',String(Math.round(value)));try{localStorage.setItem('previs-scene-width',String(value));}catch{}}
try{const width=Number(localStorage.getItem('previs-scene-width'));setSceneWidth(width>0?width:214);}catch{setSceneWidth(214);}
sceneResize.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();sceneResize.setPointerCapture(e.pointerId);document.body.style.cursor='col-resize';});
sceneResize.addEventListener('pointermove',e=>{if(sceneResize.hasPointerCapture(e.pointerId))setSceneWidth(e.clientX);});
sceneResize.addEventListener('pointerup',e=>{if(sceneResize.hasPointerCapture(e.pointerId))sceneResize.releasePointerCapture(e.pointerId);document.body.style.cursor='';});
sceneResize.addEventListener('pointercancel',()=>{document.body.style.cursor='';});
sceneResize.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();setSceneWidth($('.scene-panel').getBoundingClientRect().width+(e.key==='ArrowRight'?16:-16));}});
